// GetNamespace gets a namespace
func (s *Server) GetNamespace(ctx context.Context, r *flipt.GetNamespaceRequest) (*flipt.Namespace, error) {
	s.logger.Debug("get namespace", zap.Stringer("request", r))
	namespace, err := s.store.GetNamespace(ctx, storage.NewNamespace(r.Key, storage.WithReference(r.Reference)))
	s.logger.Debug("get namespace", zap.Stringer("response", namespace))
	return namespace, err
}

// ListNamespaces lists the namespaces visible to the caller.
func (s *Server) ListNamespaces(ctx context.Context, r *flipt.ListNamespaceRequest) (*flipt.NamespaceList, error) {
	s.logger.Debug("list namespaces", zap.Stringer("request", r))

	ref := storage.ReferenceRequest{Reference: storage.Reference(r.Reference)}
	if value := ctx.Value(authz.NamespacesKey); value != nil {
		accessible, ok := value.([]string)
		if !ok {
			return nil, errors.ErrInvalidf("invalid accessible namespaces in context")
		}

		// Apply authorization before pagination. Filtering a store page can return
		// an empty page even when the caller has accessible namespaces later on.
		results, err := s.store.ListNamespaces(ctx, storage.ListWithOptions(ref))
		if err != nil {
			return nil, err
		}

		allowed := make(map[string]struct{}, len(accessible))
		for _, key := range accessible {
			allowed[key] = struct{}{}
		}

		filtered := make([]*flipt.Namespace, 0, len(accessible))
		for _, namespace := range results.Results {
			if namespace == nil {
				continue
			}
			if _, ok := allowed[namespace.Key]; ok {
				filtered = append(filtered, namespace)
			}
		}

		resp := &flipt.NamespaceList{TotalCount: int32(len(filtered))}
		start := int(r.Offset)
		if r.PageToken != "" {
			start, err = strconv.Atoi(r.PageToken)
			if err != nil {
				return nil, errors.ErrInvalidf("pageToken is not valid: %q", r.PageToken)
			}
		}
		if start < 0 || r.Limit < 0 {
			return nil, errors.ErrInvalidf("invalid namespace pagination parameters")
		}
		if start > len(filtered) {
			start = len(filtered)
		}

		end := len(filtered)
		if r.Limit > 0 && int(r.Limit) < end-start {
			end = start + int(r.Limit)
			resp.NextPageToken = strconv.Itoa(end)
		}
		resp.Namespaces = filtered[start:end]

		s.logger.Debug("list namespaces", zap.Stringer("response", resp))
		return resp, nil
	}

	results, err := s.store.ListNamespaces(ctx, storage.ListWithParameters(ref, r))
	if err != nil {
		return nil, err
	}

	resp := flipt.NamespaceList{
		Namespaces: results.Results,
	}

	total, err := s.store.CountNamespaces(ctx, ref)
	if err != nil {
		return nil, err
	}

	resp.TotalCount = int32(total)
	resp.NextPageToken = results.NextPageToken

	s.logger.Debug("list namespaces", zap.Stringer("response", &resp))
	return &resp, nil
}

