func TestAuthorizationRequiredInterceptor_ListNamespaces(t *testing.T) {
	tests := []struct {
		name       string
		authn      *authrpc.Authentication
		namespaces []string
		engineErr  error
		wantCalled bool
		wantEval   bool
	}{
		{
			name:       "accessible namespaces",
			authn:      adminAuth,
			namespaces: []string{"local", "staging"},
			wantCalled: true,
			wantEval:   true,
		},
		{
			name:       "no accessible namespaces",
			authn:      adminAuth,
			namespaces: []string{},
			wantCalled: true,
			wantEval:   true,
		},
		{
			name:      "evaluation error",
			authn:     adminAuth,
			engineErr: errors.New("invalid namespace decision"),
			wantEval:  true,
		},
		{
			name: "authentication required",
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			verifier := &mockPolicyVerifier{
				namespaces:    tt.namespaces,
				namespacesErr: tt.engineErr,
			}
			ctx := authmiddlewaregrpc.ContextWithAuthentication(context.Background(), tt.authn)
			called := false
			handler := func(ctx context.Context, _ any) (any, error) {
				called = true
				namespaces, ok := ctx.Value(authz.NamespacesKey).([]string)
				require.True(t, ok, "accessible namespaces must be present in context")
				assert.Equal(t, tt.namespaces, namespaces)
				return nil, nil
			}

			_, err := AuthorizationRequiredInterceptor(zap.NewNop(), verifier)(
				ctx,
				&flipt.ListNamespaceRequest{},
				&grpc.UnaryServerInfo{FullMethod: flipt.Flipt_ListNamespaces_FullMethodName},
				handler,
			)

			assert.Equal(t, tt.wantCalled, called)
			assert.Equal(t, 0, verifier.isAllowedCalls)
			if tt.wantEval {
				assert.Equal(t, 1, verifier.namespacesCalls)
				assert.Equal(t, map[string]any{"authentication": tt.authn}, verifier.namespacesInput)
			} else {
				assert.Equal(t, 0, verifier.namespacesCalls)
			}

			if tt.wantCalled {
				require.NoError(t, err)
			} else {
				require.Equal(t, errUnauthorized, err)
			}
		})
	}
}

