export default function App() {
  const theme = useSelector(selectTheme);
  const [systemPrefersDark, setSystemPrefersDark] = useState(
    window.matchMedia('(prefers-color-scheme: dark)').matches
  );

  useEffect(() => {
    window
      .matchMedia('(prefers-color-scheme: dark)')
      .addEventListener('change', (e) => setSystemPrefersDark(e.matches));
  }, []);

  useEffect(() => {
    if ((theme === Theme.SYSTEM && systemPrefersDark) || theme === Theme.DARK) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [theme, systemPrefersDark]);

  const { ui } = useSelector(selectConfig);

  const namespace = useSelector(selectCurrentNamespace);

  let title = `Flipt · ${namespace.key}`;
  if (ui.topbar?.label) {
    title = `Flipt/${ui.topbar.label} · ${namespace.key}`;
  }

  return (
    <>
      <Helmet>
        <meta charSet="utf-8" />
        <title>{title}</title>
        <link rel="icon" href="/favicon.svg" />
        <meta name="viewport" content="width=device-width, initial-scale=1.0" />
      </Helmet>
      <SessionProvider>
        <RouterProvider router={router} />
      </SessionProvider>
    </>
  );
}
import { useEffect, useState } from 'react';
import { useSelector } from 'react-redux';
import {
  Navigate,
  Outlet,
  useLocation,
  useMatches
} from 'react-router-dom';
import Footer from '~/components/Footer';
import Header from '~/components/Header';
import Loading from '~/components/Loading';
import { NotificationProvider } from '~/components/NotificationProvider';
import ErrorNotification from '~/components/notifications/ErrorNotification';
import SuccessNotification from '~/components/notifications/SuccessNotification';
import Sidebar from '~/components/Sidebar';
import { useSession } from '~/data/hooks/session';
import { useAppDispatch } from '~/data/hooks/store';
import { LoadingStatus } from '~/types/Meta';
import { fetchInfoAsync, selectConfig } from './meta/metaSlice';
import {
  currentNamespaceChanged,
  useListNamespacesQuery
} from './namespaces/namespacesSlice';
import CommandDialog from '~/components/command/CommandDialog';
import Banner from '~/components/Banner';
import { selectDismissedBanner } from './events/eventSlice';
import { RootState } from '~/store';
import { addNamespaceToPath } from '~/utils/helpers';

function InnerLayout() {
  const { session } = useSession();
  const [sidebarOpen, setSidebarOpen] = useState(false);

  const dismissedBanner = useSelector(selectDismissedBanner);
  const dispatch = useAppDispatch();

  const matches = useMatches();
  const namespaceKey = matches.find((match) => match.params.namespaceKey)?.params
    .namespaceKey;
  const location = useLocation();
  const currentNamespaceKey = useSelector(
    (state: RootState) => state.namespaces.currentNamespace
  );
  const config = useSelector(selectConfig);
  const namespaces = useListNamespacesQuery();

  useEffect(() => {
    if (
      namespaceKey &&
      namespaces.data?.namespaces.some(
        (namespace) => namespace.key === namespaceKey
      ) &&
      currentNamespaceKey !== namespaceKey
    ) {
      dispatch(currentNamespaceChanged({ key: namespaceKey }));
    }
  }, [namespaceKey, namespaces.data, currentNamespaceKey, dispatch]);

  useEffect(() => {
    dispatch(fetchInfoAsync());
  }, [dispatch]);

  if (!session) {
    return <Navigate to="/login" />;
  }

  if (namespaces.isLoading || config.status != LoadingStatus.SUCCEEDED) {
    return <Loading fullScreen />;
  }

  const accessibleNamespaces = namespaces.data?.namespaces ?? [];
  const preferredNamespace =
    accessibleNamespaces.find(
      (namespace) => namespace.key === currentNamespaceKey
    ) ?? accessibleNamespaces[0];
  const namespaceInURLIsUnavailable =
    namespaceKey &&
    !accessibleNamespaces.some((namespace) => namespace.key === namespaceKey);
  const isUnscopedNamespacePage =
    location.pathname === '/' ||
    /^\/(flags|segments|console)(\/|$)/.test(location.pathname);

  if (
    preferredNamespace &&
    (namespaceInURLIsUnavailable ||
      (!namespaceKey && isUnscopedNamespacePage))
  ) {
    return (
      <Navigate
        to={{
          pathname: addNamespaceToPath(
            location.pathname,
            preferredNamespace.key
          ),
          search: location.search,
          hash: location.hash
        }}
        replace
      />
    );
  }

  return (
    <>
      <Sidebar setSidebarOpen={setSidebarOpen} sidebarOpen={sidebarOpen} />
      <div className="flex min-h-screen flex-col bg-background md:pl-64">
        <Header setSidebarOpen={setSidebarOpen} />
        {!dismissedBanner && (
          <Banner
            title="Introducing Flipt Cloud"
            description="Fully managed Flipt. Multiple Environments. Integrated with your Git Repositories."
            href="https://docs.flipt.io/cloud/overview"
          />
        )}
        <main className="flex pt-1 sm:pt-4">
          <div className="mx-auto w-full max-w-screen-lg overflow-x-auto px-4 sm:px-6 lg:px-8">
            <Outlet />
          </div>
        </main>
        <Footer />
        <CommandDialog />
      </div>
    </>
  );
}

